import rospy
from typing import Type, Any, TYPE_CHECKING
from ..logger.logger import logger

if TYPE_CHECKING:
    from .node import ROS1Node


class ROS1Publisher:
    def __init__(
        self,
        node: "ROS1Node",
        msg_type: Type,
        topic: str,
        qos_profile: int = 10,
        **kwargs
    ):
        """
        创建ROS1发布者

        Args:
            node: ROS1Node实例
            msg_type: 消息类型
            topic: 话题名称
            qos_profile: 队列大小（对应ROS2的qos_profile）
            **kwargs: 其他参数传递给rospy.Publisher
        """
        self._node = node
        self._msg_type = msg_type
        self._topic = topic
        self._publisher = rospy.Publisher(
            topic, msg_type, queue_size=qos_profile, **kwargs
        )

    def publish(self, msg: Any):
        """
        发布消息

        Args:
            msg: 要发布的消息对象
        """
        self._publisher.publish(msg)

    @property
    def topic(self) -> str:
        """获取话题名称"""
        return self._topic

    @property
    def msg_type(self) -> Type:
        """获取消息类型"""
        return self._msg_type

    def destroy(self):
        """销毁发布者"""
        self._publisher.unregister()
